import Foundation

private typealias E = EvidenceSeed

/// Follow-up trials for the batch AO everyday-crime stories.
extension FollowUpCases {
    static let batchAO: [CaseTemplate] = [vendingAgain, busStopThreat, tireResale, deerStandAgain, flagBurn, collectionPlateTheft, skateboardEscape, fireAlarmAgain, clotheslineTheft, softballThreat, ticketScalperTwo, cameraSmashAssault, rideshareRunnerTwo, parkingLotDispute, burglaryReceiving, pwisdAgain, dvpoViolationText, snatchCardUse, forgedCheckUttering, dwellingRaid, atvChopShop, deputyResist, felonFirearmPossession, cokeMotelAgain, robberyIntimidation]

    static let vendingAgain = SmallCases.make(
        key: "story.followup.vendingAgain",
        category: .property,
        headlines: ["Another Vending Machine Pried Open Behind Laundromat", "Same Method, New Machine for Defendant From Earlier Case"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a vending machine, causing damage of $510, on {DATE}.",
        ages: 18...45,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, another vending machine was pried open behind a laundromat. A deputy found {D} nearby with a screwdriver and $22 in quarters. {D.He} says {D.he} found the quarters.",
        state: [E(.physical, 3, "Screwdriver and Quarters", "A bent screwdriver and $22 in quarters.", .search), E(.video, 2, "Laundromat Camera", "A figure pries at the coin door.")],
        defense: [E(.statement, 1, "Found", "{DL} says {D.he} found the quarters in a parking lot.")],
        role: "Sheriff's deputy",
        exam: [.direct("What were you called to behind the laundromat?", "\"The owner reported someone prying at a vending machine near the back door at night, and I arrived within a few minutes.\""), .direct("What did you find when you arrived?", "\"{DL} was standing near the machine, and the coin door had been pried open with something bent.\""), .direct("What did you find on {DL}?", "\"A bent screwdriver in {D.his} hand and about twenty-two dollars in quarters in {D.his} jacket pocket.\""), .direct("What does the laundromat camera show?", "\"It shows a figure working at the coin door with a tool for several minutes before the deputies arrived.\""), .direct("What was the damage?", "\"The coin door was bent and the lock broken, and the owner estimated five hundred ten dollars to repair it.\""), .direct("What did {DL} tell you about the quarters?", "\"{D.He} said {D.he} found the quarters in a parking lot and didn't know where they came from.\""), .cross("{DL} didn't run when you arrived?", "\"No, {D.he} stayed where {D.he} was and spoke with me calmly.\""), .cross("The camera doesn't show a face clearly, does it?", "\"The image is dark and grainy, and I can't make out features, only a figure at the door.\""), .cross("Quarters are common, aren't they?", "\"Yes, and many people carry them for laundry. The amount alone doesn't prove where they came from.\""), .cross("Nothing was reported missing from the machine?", "\"The owner couldn't say exactly how many quarters were inside, so we couldn't match them.\""), .cross("The screwdriver is an ordinary tool?", "\"Yes, it's a common screwdriver that anyone could own or carry.\"")],
        theory: ("{D} pried another machine.", "A screwdriver and coins."),
        allocution: "\"I'm done with all of it. I had a screwdriver on me because I use it for work, and the quarters were change I'd found, and I'm sorry how it looked behind that laundromat. I've been in this courtroom before and I don't want to come back. I'll stay away from those machines.\"",
        truths: ("{DL}'s thumb print was on the coin door.", "The screwdriver was a mechanic's and {DL} had borrowed it."),
        defendant: [.direct("Why were you behind the laundromat?", "\"I was waiting for a ride and sat near the back door out of the wind. I wasn't there to touch anything.\""), .direct("What were you doing with the screwdriver?", "\"I use it for odd jobs and had it in my hand to tighten a loose strap on my backpack.\""), .direct("Where did the quarters come from?", "\"I found them in a parking lot a few hours earlier, and I had put them in my pocket for the laundry.\""), .direct("Did you pry the machine open?", "\"No. I never touched the machine. The door was already bent when I came around the corner.\""), .direct("What happened when the deputy arrived?", "\"I stayed where I was and answered the deputy's questions. I told the deputy exactly what I told you.\""), .direct("What would you tell the court?", "\"I'd ask the court to see that I wasn't trying to take anything. I was waiting for a ride and was in the wrong place.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I understand why that looks bad. I still didn't do this.\""), .cross("You had a screwdriver and quarters at a vending machine that had been pried?", "\"Yes, and I see how that looks. I didn't pry it, and I'm telling the truth.\""), .cross("You say you found twenty-two dollars in quarters?", "\"Yes, in a parking lot, over time. I know it sounds strange, but it's true.\""), .cross("You were alone behind the building at night?", "\"I was waiting for a ride and didn't think I'd be questioned for being there.\""), .cross("The camera shows a figure at the machine?", "\"It does, but I can't see who it is, and I'd ask the court to look closely at that.\"")],
        openings: ("A deputy found {D} near the machine, behind a laundromat, with a screwdriver and $22 in quarters after the coin door was pried open. The laundromat camera shows a figure at the door, and {DL} had stood in this court in {PRIORDATE} over {PRIOR}.", "The defense will say {D} found the quarters in a parking lot and was standing near the machine for another reason. {D} did not touch the coin door."),
        closings: ("The coin door was bent open, and {D} was standing next to it with a screwdriver and quarters. After {PRIOR}, {DL} knew what this looked like.", "A figure on a camera is not {D}, and a screwdriver is a common tool. The State must prove {D} pried the door and took the coins."),
        timeline: [(0, "Late night: the coin door is pried."), (0, "A deputy stops {DL} nearby.")],
        identified: "A deputy's patrol.",
        impact: "It's the third time this year, and each time I have to pay for the repair and the lost sales. The coin box was pried off behind the laundromat, and the lock plate was bent again. I run these machines on thin margins, and each break-in costs me a week's profit.",
        genders: ["D": .male])

    static let busStopThreat = SmallCases.make(
        key: "story.followup.busStopThreat",
        category: .publicOrder,
        headlines: ["Parent Threatens Bus Driver Weeks After Stop Dispute", "Communicating Threats Charge After School Bus Incident"],
        law: "communicatingThreats",
        spec: "Willfully threatened to physically injure {V}, a school bus driver, on {DATE}.",
        ages: 24...55,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} approached {V}, the driver, at the school lot and said 'I'll see you in the parking lot someday.' A teacher heard it.",
        state: [E(.statement, 3, "Teacher", "A teacher heard the threat."), E(.document, 2, "Incident Report", "Filed the same day.")],
        defense: [E(.statement, 1, "Venting", "{DL} says it wasn't meant as a threat.")],
        role: "School bus driver",
        exam: [.direct("What is your job?", "\"I drive a school bus on a morning and afternoon route and I'm responsible for a full load of children every day.\""), .direct("What happened at the school lot?", "\"{DL} approached me by my bus after I parked and said, 'I'll see you in the parking lot someday.'\""), .direct("Why did that frighten you?", "\"{DL} had been in court over a dispute with me, and the way {D.he} said it made me feel I was being warned.\""), .direct("Who else heard it?", "\"A teacher who was walking nearby heard the whole thing and told me afterward that it sounded like a threat.\""), .direct("What did you do?", "\"I reported it to my supervisor the same day, and we filed an incident report with the school and the sheriff's office.\""), .direct("How has it affected your work?", "\"I look at the lot differently now and keep my phone in my pocket when I'm outside the bus with children around.\""), .cross("{DL} didn't touch you?", "\"No, there was no physical contact. {D.He} said it and walked away.\""), .cross("{DL} didn't mention a weapon?", "\"No weapon was mentioned. It was only the words and the way {D.he} said them.\""), .cross("It could be read as a casual remark?", "\"Some might read it that way, but I took it as a threat given the history between us.\""), .cross("{DL} didn't come back to the lot later?", "\"Not that I know of. I haven't seen {D.him} near my bus since that day.\""), .cross("The teacher is the only witness?", "\"She's the only person who told me she heard it, though other staff were in the lot.\"")],
        theory: ("{D} threatened the driver.", "Angry words."),
        allocution: "\"I was picking up my son at the school lot, and I said something in anger that was just talk. I didn't mean it as a threat, and I've been in this courtroom before and know how it sounds. I'll keep my distance from {V} and keep my mouth shut.\"",
        truths: ("{DL} waited by the lot for an hour.", "{V} had been rough with {DL}'s son, a child said."),
        defendant: [.direct("What did you say to the driver?", "\"I said something like 'I'll see you in the parking lot someday.' I said it out of anger and then walked away.\""), .direct("What did you mean?", "\"I meant that we would run into each other again and I wasn't done being upset. I didn't mean to hurt anyone.\""), .direct("Why were you at the school?", "\"I was picking up my child and saw the driver. It was the first time since the court case.\""), .direct("Did you plan to do anything?", "\"No. I never planned to approach the driver or do anything. It came out in the moment, and I regret it.\""), .direct("How did you feel afterward?", "\"I felt ashamed. I knew right away I'd said something I shouldn't have in front of the school.\""), .direct("What would you say to the driver?", "\"I'm sorry for scaring you. I'll stay away from you and the bus lot, and I'll keep my feelings to myself.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I knew better than to say anything to the driver. I let my anger win.\""), .cross("You said you'd see the driver in the parking lot?", "\"I did, and I understand how it sounds. I didn't mean it as a promise to hurt anyone.\""), .cross("A teacher heard you say it?", "\"Yes, and I'm embarrassed it was said where a teacher and children could hear.\""), .cross("You knew the driver works with children?", "\"Yes, and that makes it worse. A bus lot is a place people should feel safe.\""), .cross("You'll stay away from the school lot?", "\"I'll have someone else do the pickups, and I won't go near that bus or that driver again.\"")],
        openings: ("{D} approached {V}, a school bus driver, at the school lot and said, 'I'll see you in the parking lot someday,' where a teacher heard it, and {DL} had already appeared here in {PRIORDATE} over {PRIOR}.", "The defense will say the words were angry and not a threat. {D} did not touch {V}, and the remark was not a plan to meet and fight."),
        closings: ("The words were aimed at a bus driver responsible for a busload of children, and a teacher heard them. After {PRIOR}, {DL} knew a statement like this would be taken seriously.", "Words spoken in anger are not a threat unless they are meant to be one. {D} walked away, and the State must prove {D} meant {V} to fear harm."),
        timeline: [(0, "Afternoon: {DL} at the school lot."), (0, "The teacher hears it.")],
        identified: "A teacher and the incident report.",
        impact: "I ask for an escort now when I walk out to my bus. {D.He} told me {D.he}'d see me in the parking lot someday, and a teacher heard it. I've driven children for fifteen years and never worried about a parent. Now I look over my shoulder in a lot full of kids.",
        genders: ["D": .male])

    static let tireResale = SmallCases.make(
        key: "story.followup.tireResale",
        category: .property,
        headlines: ["Used Tires Sold From Same Yard Where Rims Were Found", "Second Stolen Tire Case"],
        law: "possStolen",
        spec: "Possessed four tires valued at $520 belonging to {V}, knowing them stolen, on {DATE}.",
        ages: 20...58,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, four tires stolen from a different truck were found stacked in {D}'s yard with the DOT codes sanded. {DL} says {D.he} resells tires.",
        state: [E(.physical, 3, "The Tires", "Four tires with sanded codes matching {V}'s invoice.", .search), E(.document, 2, "Invoice", "{V}'s receipt.")],
        defense: [E(.statement, 1, "Resale", "{DL} says {D.he} buys and sells used tires.")],
        role: "Sheriff's deputy",
        exam: [.direct("How did your investigation begin?", "\"{V} reported four tires stolen from a truck, with an invoice showing brand, size, and the serial numbers on the tires.\""), .direct("What did you find at {DL}'s property?", "\"Four tires stacked in {D.his} yard, matching the brand and size on {V}'s invoice, with the DOT codes sanded off.\""), .direct("What are the DOT codes?", "\"They're stamped on every tire and show where and when it was made, and they trace a tire to an owner.\""), .direct("Why does it matter that they were sanded?", "\"A seller who removes a code is usually trying to prevent a tire from being traced back to where it came from.\""), .direct("How did you match them to {V}'s tires?", "\"Faint remnants of the codes and the tread wear matched the invoice and photographs {V} had kept.\""), .direct("What did {DL} say about the tires?", "\"{D.He} said {D.he} buys and sells used tires and didn't know these were stolen.\""), .cross("{DL} does buy and sell used tires, doesn't {D.he}?", "\"Yes, {D.he} has a small resale business, and there were other used tires in the yard.\""), .cross("Used tires often have worn or missing codes?", "\"Sometimes, but these showed sanding marks, which is different from ordinary wear.\""), .cross("You can't say who sanded the codes?", "\"No. I can only say the codes were removed. I don't know by whom.\""), .cross("{DL} didn't try to hide the tires?", "\"They were stacked in plain view in {D.his} yard, so no, {D.he} didn't hide them.\""), .cross("{DL} cooperated with the search?", "\"Yes, {D.he} allowed us in and answered questions without argument.\"")],
        theory: ("{D} had more stolen tires.", "A tire reseller."),
        allocution: "\"I'll stop buying used tires from strangers. A man sold me those four tires, and they were old, and I didn't look closely at the DOT codes. I resell tires for a living, and I've been in this courtroom before. I'm sorry to the owner, and I'll help return them.\"",
        truths: ("{DL} was on camera at {V}'s house.", "The seller was arrested later."),
        defendant: [.direct("Where did you get the tires?", "\"I bought them from a man who said he was clearing out a garage, and he gave me a good price.\""), .direct("What do you do with used tires?", "\"I buy them cheap, clean them up, and sell them to people who can't afford new ones.\""), .direct("Why did the codes look sanded?", "\"They were that way when I got them. Some sellers sand them to hide wear, and I didn't think about it.\""), .direct("Did you know they were stolen?", "\"No. I never knew where they came from or who owned them. I wouldn't have bought them if I had.\""), .direct("What happened when the deputies came?", "\"I let them in, showed them the tires, and told them who sold them to me, though I only knew his first name.\""), .direct("What would you do differently?", "\"I'd ask for a receipt every time and refuse anything with missing codes or a story that doesn't add up.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I know I should have been more careful about where I buy. That's what I regret.\""), .cross("You bought four tires with the codes removed?", "\"Yes, I did. I should have asked why, and I didn't.\""), .cross("You can't name the seller?", "\"I only have a first name. I never asked for more and I should have.\""), .cross("You paid far less than they were worth?", "\"I paid a low price, and I told myself it was a bargain. It should have been a warning.\""), .cross("You'll return the tires to {V}?", "\"Yes, I'd like to give them back and pay what the court thinks is fair.\"")],
        openings: ("Four tires stolen from {V}'s truck were found stacked in {D}'s yard with the DOT codes sanded off, matching the brand and size on {V}'s invoice, and this was not {DL}'s first time here, after {PRIOR} in {PRIORDATE}.", "The defense will present a man who buys and sells used tires for a living. {D} bought these in a lot of used tires, and did not know any were stolen."),
        closings: ("Sanded codes and a matching brand and size, four tires in {D}'s yard. After {PRIOR}, {DL} knew what a sanded DOT code means.", "A used tire dealer buys by the lot and cannot trace every tire. The State must prove {D} knew these four were stolen."),
        timeline: [(0, "Night: the tires are taken."), (5, "A deputy finds them.")],
        identified: "A deputy's search.",
        impact: "It's my second time as a victim, too. I came out to find my truck on blocks and the wheels gone, and I missed days of work. I found out later they'd been sitting in a yard with the numbers sanded off. I can't afford new tires every year.",
        genders: ["D": .male])

    static let deerStandAgain = SmallCases.make(
        key: "story.followup.deerStandAgain",
        category: .property,
        headlines: ["Hunter Back on Posted Land With New Stand", "Second Trespass for Man From Hunting Case"],
        law: "trespass2",
        spec: "Entered and remained on the premises of {V}, a posted hunting tract, after being notified not to enter, on {DATE}.",
        ages: 24...66,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V}'s trail camera caught {D} in a new stand on the same tract after new signs went up. {DL} says the new signs were further than the property line.",
        state: [E(.video, 3, "Trail Camera", "{D} in a new stand at dawn."), E(.physical, 2, "Signs", "Fresh signs every 50 feet.")],
        defense: [E(.statement, 1, "Line", "{DL} says the signs were off the line.")],
        role: "Wildlife officer",
        exam: [.direct("What were you asked to investigate?", "\"{V} reported a hunter in a stand on a posted tract after being told not to enter, and gave me trail camera pictures.\""), .direct("What do the trail camera pictures show?", "\"They show {DL} climbing into a new stand at dawn, in camouflage, with a bow, on the same tract.\""), .direct("What signs did you see?", "\"Fresh posted signs about every fifty feet along the property line, with the owner's name and phone number.\""), .direct("Why is this the same tract?", "\"{DL} was told after the earlier case to stay off the property, and the tract is the one in the earlier case.\""), .direct("How did {V} notify {DL}?", "\"In writing, and the owner put up new signs after the earlier case so the boundary was clearer.\""), .direct("What did {DL} say?", "\"{D.He} said the new signs were farther out than the line and {D.he} thought the stand was on the open side.\""), .cross("The tract is large and wooded, isn't it?", "\"Yes, hundreds of acres, and the line is not always easy to see in the woods.\""), .cross("{DL} didn't conceal the stand?", "\"It was in a tree, in plain view of the trail camera, though not easy to see from the ground.\""), .cross("The signs are every fifty feet?", "\"Yes, along the line, but in thick brush a hunter might miss one.\""), .cross("You can't say exactly where the line is without a survey?", "\"A survey is the only precise way, and I used the owner's map to place the stand inside it.\""), .cross("{DL} left when you asked?", "\"Yes, {D.he} climbed down and left without any argument.\"")],
        theory: ("{D} returned after the earlier case.", "A line moved."),
        allocution: "\"I'll hunt elsewhere. I thought that new stand was off the property line, and I didn't see the signs. I've been in this courtroom before about the same tract, and I know I should have walked the line first. I'm sorry for the trouble to {V}.\"",
        truths: ("{DL} had a map marking the stand.", "A survey was never done."),
        defendant: [.direct("Why were you in that stand?", "\"I hunt the adjoining land and put my stand where it looked like the property line to me.\""), .direct("Did you see the new signs?", "\"I saw signs, but I thought they were set back from the actual line, and I thought I was on the open side.\""), .direct("Did you know the tract was posted against you?", "\"I knew the owner didn't want me there after the earlier case. I believed I'd stayed outside the posted line.\""), .direct("Why did you go at dawn?", "\"That's when the deer move. I wasn't trying to hide, and I'd hunted the area for years before.\""), .direct("What happened when the officer arrived?", "\"I climbed down, told the officer the same thing I told you, and left when asked.\""), .direct("What would you tell the court?", "\"I didn't mean to cross the line. I'll get a survey and stay well off that tract from now on.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I should have been much more careful about where the line was after that.\""), .cross("You'd been told in writing not to enter?", "\"I had, and I should have stayed far from the line instead of guessing.\""), .cross("Fresh signs went up every fifty feet?", "\"Yes, and I should have paid closer attention to them. I'm sorry I didn't.\""), .cross("You hunted in a new stand on that tract?", "\"It was a new stand, and I put it where I believed I was allowed. I was wrong.\""), .cross("You'll stay off the land?", "\"I will. I'll pay for a survey if it helps settle where the line really is.\"")],
        openings: ("{V}'s trail camera caught {D} climbing into a new stand at dawn on the same tract, after fresh signs went up every fifty feet, and {DL} had faced this court in {PRIORDATE} over {PRIOR}.", "The defense will say the new signs were placed past the line, and {D} believed the stand was on the part of the land {D.he} had permission to use."),
        closings: ("The signs were new and every fifty feet, and {D} had already been told to stay out after {PRIOR}. The camera shows {D} in the stand.", "The signs sit beyond the line, and {D} reasonably believed the stand was outside the posted area. The State must prove {D} knew {D.he} was trespassing."),
        timeline: [(0, "5:15 a.m.: {DL} enters the tract.")],
        identified: "{V}'s trail camera.",
        impact: "Every season it's the same. We post the land, and we paint the trees, and then we find a stranger in a stand. I lease this tract to my son, and I'm tired of going out to check cameras. I'd just like hunters to respect a line when they see it.",
        genders: ["D": .male])

    static let flagBurn = SmallCases.make(
        key: "story.followup.flagBurn",
        category: .property,
        headlines: ["Flag Burned on Veteran's Lawn", "Property Damage Charge After Flag Theft Case"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a flag and flagpole, by fire, causing damage of $260, on {DATE}.",
        ages: 18...30,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V}'s replacement flag was set on fire at 1 a.m. A neighbor's camera showed a figure in a hoodie. {D} says {D.he} was home.",
        state: [E(.video, 3, "Neighbor's Camera", "A figure lights the flag with a lighter."), E(.physical, 2, "Burned Flag", "The flag charred to the pole.")],
        defense: [E(.statement, 1, "Home", "{DL}'s mother says {D.he} was home.")],
        role: "Sheriff's deputy",
        exam: [.direct("What were you called to at one in the morning?", "\"A neighbor called about a fire in {V}'s front yard. I arrived to find the flag burned down to the pole.\""), .direct("What did the neighbor's camera show?", "\"A figure in a hooded sweatshirt walked up to the pole, held a lighter to the flag, and walked away as it caught.\""), .direct("What was the damage?", "\"The flag was charred to the pole and the pole was scorched, about two hundred sixty dollars to replace both.\""), .direct("Why does this flag matter to {V}?", "\"It was a replacement for a flag that had been taken before, and {V} had put it up again after the earlier case.\""), .direct("Why did you look at {DL}?", "\"{DL} and {V} had a history from the earlier case, and {DL} lives within walking distance.\""), .direct("What did {DL} tell you?", "\"{D.He} said {D.he} was home that night, and {D.his} mother said the same when I called her.\""), .cross("The figure's face is not visible?", "\"No, the hood covers most of the face and the camera is far from the pole.\""), .cross("You can't say how tall the person is?", "\"Only that the figure appears to be of average height and build.\""), .cross("{DL}'s mother says {D.he} was home?", "\"Yes, she told me {D.he} was home all night and she heard {D.him} in the house.\""), .cross("No one saw {DL} near the flag?", "\"No, none of the neighbors reported seeing {D.him} that night.\""), .cross("There's no lighter or accelerant tied to {DL}?", "\"No. We didn't recover a lighter or anything else that could be linked to {D.him}.\"")],
        theory: ("{D} burned the veteran's flag.", "A boy at home."),
        allocution: "\"I'm sorry for what happened to that flag. I was home that night, and I've never touched it. I know about my last case, and I know people think of me when something like this happens. I'd never burn a flag, and I hope the real person is found.\"",
        truths: ("{DL}'s lighter was found in the truck.", "A friend later admitted setting it."),
        defendant: [.direct("Where were you at one in the morning?", "\"I was at home. My mother was there, and I was in my room on my computer until I went to sleep.\""), .direct("Do you know who burned the flag?", "\"No. I only heard about it afterward from the deputy. I didn't do it and I don't know who did.\""), .direct("Do you own a hooded sweatshirt?", "\"Yes, a gray one, but like many people. I wasn't wearing it that night and I never went to {V}'s yard.\""), .direct("How do you feel about {V}?", "\"I'm not happy with how the earlier case went, but I would never burn someone's flag over it.\""), .direct("What did you tell the deputy?", "\"I told the deputy where I was and gave my mother's name so the deputy could ask her.\""), .direct("What would you ask the court?", "\"To look for who really did this and not stop at me because of my record.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I understand why people look at me. That doesn't make me guilty of this.\""), .cross("You live close to {V}?", "\"A short walk, yes. That's all it proves about me and doesn't say I did anything.\""), .cross("You were upset about the earlier case?", "\"I was, and I told the court so then. I never took it out on anyone.\""), .cross("Only your mother says you were home?", "\"She's the only one, but she was in the house and she's telling the truth.\""), .cross("The person on the video wore a hood like yours?", "\"Like a lot of people's. I can't see anything on the video that shows it was me.\"")],
        openings: ("A neighbor's camera shows a figure in a hoodie hold a lighter to {V}'s replacement flag at one in the morning, and it burned down to the pole, and {DL} had been before this court in {PRIORDATE} over {PRIOR}.", "The defense will present {D}'s mother, who says {D.he} was home that night. The hood hides the face on the camera, and no one can say who was under it."),
        closings: ("{V} replaced the flag after the first time and lost it again, and {D} had come through this court before, over {PRIOR}. The figure on the camera matches {D}.", "A hoodie and a lighter do not name anyone, and {D} was home. The State must connect the figure on the camera to {D}."),
        timeline: [(0, "1 a.m.: the flag burns.")],
        identified: "A neighbor's camera.",
        mood: .wantsConviction,
        impact: "I flew it for forty years. The first one was stolen, and my neighbors helped me buy the replacement. Then at one in the morning someone set it on fire. I served this country, and I stood at that pole each morning. It broke something in me.",
        genders: ["V": .male])

    static let collectionPlateTheft = SmallCases.make(
        key: "story.followup.collectionPlateTheft",
        category: .property,
        headlines: ["Collection Plate Taken During Church Service", "Second Church Theft for Man in Donation Box Case"],
        law: "misdLarceny",
        spec: "Stole $164 in cash from a collection plate belonging to {V}, a church, on {DATE}.",
        ages: 20...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} walked out of a different church with the collection plate during the last hymn. A usher gave chase.",
        state: [E(.video, 3, "Church Camera", "{D} lifts the plate and walks out."), E(.statement, 2, "Usher", "The usher chased {D}.")],
        defense: [E(.statement, 1, "Mistake", "{DL} says {D.he} thought the plate was for visitors.")],
        role: "Church usher",
        exam: [.direct("What were you doing at the service that day?", "\"I was serving as an usher, passing the collection plate during the last hymn and standing near the back.\""), .direct("What did you see?", "\"A man I didn't know picked up the plate from the table at the back, tucked it under his arm, and walked out.\""), .direct("What did you do?", "\"I followed him outside and called to him to stop, and I chased him across the parking lot until he got into a car.\""), .direct("What does the church camera show?", "\"It shows {DL} lifting the plate from the table and walking out through the side door during the hymn.\""), .direct("How much was in the plate?", "\"About one hundred sixty-four dollars in cash and checks from that service, which we counted afterward.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} thought the plate was for visitors and meant to put money in, and that {D.he} took it by mistake.\""), .cross("You didn't know {DL}?", "\"No, I'd never seen {D.him} at our church. It's a small congregation and I know most faces.\""), .cross("The plate sits on a table at the back?", "\"Yes, it's where we leave it between passes during the service.\""), .cross("{DL} walked out, not ran?", "\"At first {D.he} walked. When I called out, {D.he} began to hurry to the car.\""), .cross("You can't say what was in {DL}'s mind?", "\"No. I can only tell you what I saw and what the camera recorded.\""), .cross("The money was never recovered?", "\"Some of the checks were returned later, but the cash was not found.\"")],
        theory: ("{D} took a collection plate.", "A confused visitor."),
        allocution: "\"I came into that church confused, and I thought the plate was meant for me because I was down on my luck. I got scared when the usher chased me and ran. I've been in this courtroom before. I should have asked for help instead, and I'll return what I can.\"",
        truths: ("{DL} had visited three churches that month.", "The plate was handed to {DL} by a child."),
        defendant: [.direct("Why were you at that church?", "\"I'd gone in to sit quietly because I was having a hard week, and I didn't know anyone there.\""), .direct("Why did you pick up the plate?", "\"I thought it was meant for visitors to add something, and I picked it up without thinking.\""), .direct("Why did you walk out with it?", "\"I panicked when the usher called out. I knew how it looked, and I should have stopped right then.\""), .direct("What happened to the money?", "\"I'm not proud of it. I spent some of it before I understood how wrong it was.\""), .direct("What did you tell the deputy?", "\"I told the deputy I'd taken it. I said I'd pay back whatever I could.\""), .direct("What would you say to the church?", "\"I'm sorry for what I did in a place of worship. I'll repay every dollar and stay away.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I knew better than to take anything from a church. I let my bad week excuse it.\""), .cross("You said you thought it was for visitors?", "\"I did say that, but I know a collection plate isn't for taking. I shouldn't have said it.\""), .cross("You walked out during the last hymn?", "\"Yes, when everyone was singing. I thought no one would notice, and I was wrong.\""), .cross("You ran when the usher chased you?", "\"I did. I was frightened and ashamed, and I should have stayed and explained.\""), .cross("You'll repay the church?", "\"Yes. I'll work out a payment plan so the full amount goes back to them.\"")],
        openings: ("During the last hymn at a different church, {D} lifted the collection plate from the table at the back and walked out, and an usher chased {DL}. The church camera shows it, and {DL} had stood in this court in {PRIORDATE} over {PRIOR}.", "The defense will say {D} was a visitor who thought the plate was meant for guests. {D} walked out with it in plain view, not in secret."),
        closings: ("The plate was taken during the hymn, the usher chased {D}, and {D} had faced this court before, over {PRIOR}. The camera shows the plate leaving the church.", "A confused visitor who carried a plate out in front of everyone did not act like a thief. The State must prove {D} meant to keep the money."),
        timeline: [(0, "Sunday: the last hymn.")],
        identified: "The usher's chase.",
        impact: "It was our mission offering, and it paid for the trip to build a church clinic. Someone walked out with the plate during the last hymn, and I chased {D.him} into the parking lot. It was the whole congregation's gift. Our members dug deep that Sunday.",
        genders: ["D": .male])

    static let skateboardEscape = SmallCases.make(
        key: "story.followup.skateboardEscape",
        category: .publicOrder,
        headlines: ["Teen Skates Away From Deputy Again", "Resisting Charge Follows Church Steps Case"],
        law: "resisting",
        spec: "Willfully resisted, delayed, and obstructed a public officer, a sheriff's deputy, on {DATE}.",
        ages: 18...26,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} skated away from a deputy who stopped to ask about a bicycle, then threw the board and ran.",
        state: [E(.video, 3, "Body Camera", "{D} skates away and runs."), E(.document, 2, "Report", "The deputy was investigating a stolen bicycle.")],
        defense: [E(.statement, 1, "Scared", "{DL} says {D.he} was scared of deputies.")],
        role: "Sheriff's deputy",
        exam: [.direct("Why did you stop to speak with {DL}?", "\"I was investigating a stolen bicycle report, and {DL} was riding on a skateboard near where the bicycle was last seen.\""), .direct("What did you ask {DL}?", "\"I asked if {D.he} had seen a bicycle matching the description or knew anything about it.\""), .direct("What did {DL} do?", "\"{D.He} pushed off on the skateboard, skated away down the street, and then threw the board and ran on foot.\""), .direct("What does your body camera show?", "\"It shows me approaching, {DL} skating away as I speak, and then running when I follow.\""), .direct("How long did the delay last?", "\"About four minutes before I caught up on foot and stopped {D.him} two blocks away.\""), .direct("What did {DL} say when you caught up?", "\"{D.He} said {D.he} was scared of deputies after the earlier case and ran without thinking.\""), .cross("{DL} wasn't the person you were looking for?", "\"No. We later found the bicycle had been taken by someone else entirely.\""), .cross("You didn't have a warrant for {DL}?", "\"No, I only wanted to ask questions. {D.He} wasn't under arrest at that point.\""), .cross("{DL} was afraid of deputies?", "\"{D.He} told me so, and I've no reason to doubt that it was part of why {D.he} ran.\""), .cross("{DL} didn't fight or strike you?", "\"No. {D.He} ran, but {D.he} never struck me or resisted when I stopped {D.him}.\""), .cross("{DL} cooperated once caught?", "\"Yes, {D.he} stopped and answered my questions without any further trouble.\"")],
        theory: ("{D} ran from a deputy.", "A scared boy."),
        allocution: "\"I was scared when that deputy stopped me about a bicycle, and I skated away, then threw my board and ran. He said stop and I didn't. I've been in this courtroom before, and I thought I was in trouble again. I should have stayed put.\"",
        truths: ("{DL} had the stolen bike's lock.", "The bike belonged to {D.his} brother."),
        defendant: [.direct("Why did you skate away?", "\"The deputy walked up and I panicked. I'd had trouble with deputies before and my first thought was to leave.\""), .direct("Why did you throw the board?", "\"It was slowing me down, and I wasn't thinking about the law. I just wanted to be away from the situation.\""), .direct("Did you know why the deputy stopped you?", "\"Not until later. I didn't know it was about a bicycle, and I hadn't taken anything.\""), .direct("What happened when the deputy caught up?", "\"I stopped and put my hands up. I told the deputy I was scared and that I should have stood still.\""), .direct("Why were you so frightened?", "\"Because of the earlier case. I felt that any contact with a deputy would end badly for me.\""), .direct("What would you tell the court?", "\"I'm sorry for running. I know the deputy was only asking questions, and I'll stand and talk next time.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and that's partly why I was afraid. It still doesn't excuse running.\""), .cross("You skated away when a deputy spoke to you?", "\"Yes, and then I ran on foot. I know that was wrong and made things worse.\""), .cross("The deputy hadn't accused you of anything?", "\"No. The deputy only asked a question. I should have answered it.\""), .cross("You delayed the investigation?", "\"I did, for a few minutes, and I understand that was a problem. I regret it.\""), .cross("You'll cooperate with deputies from now on?", "\"Yes. I'll stop and speak with them, and if I have a problem, I'll take it up with the court.\"")],
        openings: ("A deputy stopped to ask {D} about a stolen bicycle, and {D} skated away, threw the board, and ran, all on the body camera, and {DL} had already appeared here in {PRIORDATE} over {PRIOR}.", "The defense will say {D} was scared of deputies and ran out of fear, not guilt. {D} was not accused of the bicycle, and had no reason to hide."),
        closings: ("A deputy asked a simple question and {D} ran, which {DL} had done before after {PRIOR}. The body camera shows the flight.", "Running from fear is not resisting an officer. {D} did not fight or hide, and the State must prove {D} knew the deputy was trying to detain {D.him}."),
        timeline: [(0, "Afternoon: the stop.")],
        identified: "The body camera.")

    static let fireAlarmAgain = SmallCases.make(
        key: "story.followup.fireAlarmAgain",
        category: .publicOrder,
        headlines: ["Alarm Pulled at Same Apartment Complex", "Second False Alarm Charge"],
        law: "falseReport",
        spec: "Willfully made a false report that a building was on fire by pulling a fire alarm, on {DATE}.",
        ages: 20...50,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, the alarm was pulled again at 3 a.m. at the same complex. A camera showed {D} nearby. {D.He} says {D.he} was walking a dog.",
        state: [E(.video, 3, "Hallway Camera", "{D} at the pull station."), E(.document, 2, "Dispatch", "Two engines.")],
        defense: [E(.statement, 1, "Dog", "{DL} says {D.he} was walking a dog.")],
        role: "Fire captain",
        exam: [.direct("What call did you respond to at three in the morning?", "\"A fire alarm at an apartment complex we had responded to before, and two engines and a command vehicle went.\""), .direct("What did you find?", "\"There was no fire, no smoke, and no heat. The pull station on the second floor had been activated by hand.\""), .direct("What does the hallway camera show?", "\"It shows {DL} walking up to the pull station, pulling it, and walking back down the stairs and out the door.\""), .direct("What is the effect of a false alarm?", "\"It sends crews and equipment away from real emergencies, wakes residents, and puts everyone at risk on the road.\""), .direct("How did you identify {DL}?", "\"The camera image was clear, and building management recognized {D.him} as someone who had been involved in the earlier alarm.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} was walking a dog and happened to pass the stairwell when the alarm went off.\""), .cross("{DL} does live nearby, doesn't {D.he}?", "\"Yes, within a few blocks, which is why it's possible {D.he} was out with a dog.\""), .cross("Other people were in the hallway?", "\"The camera shows only {DL} at the station, though other doors were closed along the corridor.\""), .cross("You didn't see a dog on the video?", "\"No dog is visible in the camera footage.\""), .cross("{DL} stayed at the scene?", "\"No, {D.he} left the building before our crews arrived.\""), .cross("You can't say what was in {DL}'s mind?", "\"Only what the camera shows. I have to rely on the images to know what happened.\"")],
        theory: ("{D} pulled it again.", "A dog walker."),
        allocution: "\"I'm sorry for the trouble at that complex. I live there, and I was out walking my dog at three in the morning, and I never touched the alarm. I know about the last time. I hope the court can see that I'm just a resident who was in the wrong place.\"",
        truths: ("{DL} was on camera pulling it.", "The dog was a neighbor's."),
        defendant: [.direct("Where were you at three in the morning?", "\"I was walking my dog around the complex. I was out because the dog needed to go, and that's a habit of mine.\""), .direct("Did you pull the alarm?", "\"No. The alarm was already going off when I walked by the building. I never touched the pull station.\""), .direct("Why were you inside the building?", "\"I stepped in out of the cold for a moment while the dog sniffed in the entryway.\""), .direct("Why did you leave?", "\"The alarm was loud and my dog was scared. I took the dog away from the noise and went home.\""), .direct("What did you say to the deputy?", "\"I said the same thing I'm saying now. I wasn't pulling any alarms. I was just out with my dog.\""), .direct("What would you tell the court?", "\"I didn't do this. I'd ask the court to look carefully at the video and not assume it was me.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, over the earlier alarm. I know how that looks, but I didn't pull this one.\""), .cross("The camera shows you at the pull station?", "\"It shows someone at the station, and I say it's not me pulling the alarm.\""), .cross("You have no dog on the video?", "\"The dog was outside with me when the alarm sounded. It isn't in the hallway footage.\""), .cross("You left before the fire department arrived?", "\"Yes, because the noise upset my dog. I never meant to avoid anyone.\""), .cross("You've been close to that alarm before?", "\"The earlier case was real, and I paid for it. This time I wasn't the one.\"")],
        openings: ("At three in the morning the pull station on the second floor of the same complex was activated by hand, and two engines responded to a fire that did not exist. A hallway camera shows {D} nearby, and this was not {DL}'s first time here, after {PRIOR} in {PRIORDATE}.", "The defense will say {D} was walking a dog at that hour and passed the pull station without touching it. {D} did not set off the alarm."),
        closings: ("The hallway camera puts {D} at the pull station, and {D} had already been here over {PRIOR} for the same thing at the same complex.", "A man walking a dog in a hallway is not pulling an alarm. The State must prove {D} was the one who activated it."),
        timeline: [(0, "3 a.m.: the alarm.")],
        identified: "The hallway camera.",
        genders: ["D": .male])

    static let clotheslineTheft = SmallCases.make(
        key: "story.followup.clotheslineTheft",
        category: .property,
        headlines: ["Clothes Taken From Backyard Line", "Second Laundry Theft for Woman in Laundromat Case"],
        law: "misdLarceny",
        spec: "Stole clothing valued at $120 belonging to {V}, on {DATE}.",
        ages: 19...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V} found a basket of clean clothes missing from a backyard line. {D} was seen walking away carrying a basket. {D.He} says {D.he} found it on a fence.",
        state: [E(.video, 3, "Doorbell Camera", "{D} carrying a basket from {V}'s yard."), E(.physical, 2, "The Clothes", "Clean clothes in {D}'s car.", .search)],
        defense: [E(.statement, 1, "Found", "{DL} says {D.he} found the basket.")],
        role: "Sheriff's deputy",
        exam: [.direct("What did {V} report?", "\"{V} reported that a basket of clean laundry was taken from the clothesline in the backyard while {V.he} was at work.\""), .direct("What does the doorbell camera show?", "\"It shows {DL} walking out of {V}'s yard carrying a laundry basket and heading toward the street.\""), .direct("What was in the basket?", "\"About a hundred twenty dollars of clean clothing, including jeans, shirts, and some children's clothes.\""), .direct("What did you find in {DL}'s car?", "\"Clean clothes that matched {V}'s description, still folded in the same basket in the trunk.\""), .direct("How did you get permission to search?", "\"{DL} agreed to let me look in the car, and I found the clothes right away.\""), .direct("What did {DL} tell you?", "\"{D.He} said {D.he} found the basket on a fence and thought somebody had thrown it away.\""), .cross("The basket was in the yard, not on the street?", "\"The doorbell camera shows it in the yard, where {V} had hung it to dry.\""), .cross("{DL} didn't hide the basket in the car?", "\"It was in the trunk, but {D.he} opened the trunk when I asked and didn't resist.\""), .cross("{DL} was cooperative?", "\"Yes, {D.he} was cooperative from the start and helped me find the clothes.\""), .cross("The clothes were returned to {V}?", "\"Yes, all of them were returned in good condition.\""), .cross("You didn't see {DL} take the basket from the line?", "\"The camera shows {D.him} leaving with it, but not removing it from the line itself.\"")],
        theory: ("{D} took clothes from a line.", "A found basket."),
        allocution: "\"I'll replace them. I found that basket sitting on a fence and picked it up, and I didn't know it belonged to anyone. I'm sorry to {V}, and I'll make good on every piece.\"",
        truths: ("{DL}'s car had two more baskets.", "A neighbor's child had left it on the fence."),
        defendant: [.direct("Where did you get the basket?", "\"I found it on a fence at the edge of a yard, and I thought somebody had left it out for the trash.\""), .direct("Why did you pick it up?", "\"I needed clothes. Money was tight, and the basket looked abandoned, so I took it.\""), .direct("Did you know it belonged to {V}?", "\"No. I didn't know whose yard it was, and I never saw anyone around. I made a mistake.\""), .direct("What did you do when the deputy asked?", "\"I opened the trunk, showed the basket, and told the deputy where I found it.\""), .direct("What would you say to {V}?", "\"I'm sorry for taking your clothes. I should have knocked and asked, and I'll make it right.\""), .direct("What have you learned?", "\"That I can't take things I find just because they look unwanted, and I should have asked someone first.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I know better than to take something that isn't mine. I let need get ahead of me.\""), .cross("The camera shows you in {V}'s yard?", "\"Yes, it does, and I shouldn't have gone into the yard at all.\""), .cross("You said you found it on a fence?", "\"I did, and I'll admit now that it was in the yard. I'm sorry for not saying so earlier.\""), .cross("The clothes were clean and folded?", "\"They were, which should have told me someone had just washed them.\""), .cross("You'll apologize to {V}?", "\"Yes, and I'll replace anything that was damaged or lost, if there's anything.\"")],
        openings: ("{V} came home to find a basket of clean clothes missing from the backyard line, and a doorbell camera shows {D} walking out of the yard carrying a laundry basket toward the street, and {DL} had faced this court in {PRIORDATE} over {PRIOR}.", "The defense will say {D} found a basket sitting on a fence rail, thought someone had thrown it out, and picked it up in plain view of the street. {D} never knew the clothes belonged to {V}, and never went looking for anyone's clothesline."),
        closings: ("The basket was hanging in {V}'s yard when {V} left for work and gone when {V.he} returned, and the camera shows {D} carrying it out of that yard. After {PRIOR}, {DL} could not have mistaken whose clothes these were.", "A basket on a fence looks lost, not owned, and {D} carried it down a public street where anyone could see. The State must prove {D} knew the clothes belonged to {V}, and a doorbell camera cannot show what {D} knew."),
        timeline: [(0, "Midday: the basket leaves the yard.")],
        identified: "A doorbell camera.",
        impact: "They were my son's school clothes, and I'd just finished washing them. I put them on the line in the morning and came out to an empty basket. We're on a tight budget, and replacing five outfits was hard. He had to wear the same shirt three days that week.",
        genders: ["D": .female])

    static let softballThreat = SmallCases.make(
        key: "story.followup.softballThreat",
        category: .publicOrder,
        headlines: ["Coach Threatens Umpire Before Next Game", "Communicating Threats After League Fight"],
        law: "communicatingThreats",
        spec: "Willfully threatened to physically injure {V}, an umpire, on {DATE}.",
        ages: 28...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} told {V} before the next game, 'You won't walk off this field.' Players heard it.",
        state: [E(.statement, 3, "Players", "Three players heard the threat."), E(.document, 2, "League Report", "Filed by {V}.")],
        defense: [E(.statement, 1, "Joke", "{DL} says it was a joke.")],
        role: "Recreation department supervisor",
        exam: [.direct("What is your role with the league?", "\"I supervise the recreation department's softball program, including scheduling, umpires, and complaints from players.\""), .direct("What was reported to you?", "\"{V}, an umpire, reported that {DL} said before a game, 'You won't walk off this field.'\""), .direct("Who heard it?", "\"Three players from the team told me they heard it clearly, and one of them wrote it in a statement.\""), .direct("Why did {V} take it seriously?", "\"{V} said it came right after the earlier case, and {V.he} had no way to know whether it was meant.\""), .direct("What did you do?", "\"I filed a league report, removed {DL} from that evening's game, and gave the report to the sheriff's office.\""), .direct("What did {DL} say to you?", "\"{D.He} said it was a joke between players and umpires and that {D.he} didn't mean any harm.\""), .cross("Players joke with umpires all the time, don't they?", "\"They do, mostly good-natured, but this one involved a person who had been in court over {V}.\""), .cross("{DL} didn't touch {V}?", "\"No. There was no physical contact at that game or since.\""), .cross("The three players are on {DL}'s team?", "\"Two are teammates and one was on the other side. All three gave consistent statements.\""), .cross("{DL} has been a good player in the league?", "\"Yes, {D.he} has played for several seasons without other problems.\""), .cross("{DL} apologized afterward?", "\"{D.He} told me {D.he} was sorry if it was taken wrong, though {D.he} didn't apologize to {V} directly.\"")],
        theory: ("{D} threatened the umpire again.", "A joke."),
        allocution: "\"It was hot, and tempers were high before that game, and I said something I shouldn't have. I didn't mean anything by it. I'll stay off the field when {V} is working.\"",
        truths: ("{DL} walked toward {V} after saying it.", "{V} had mocked {DL} first."),
        defendant: [.direct("What did you say to the umpire?", "\"I said, 'You won't walk off this field.' It was meant as a joke about the umpire's calls, and I said it with a grin.\""), .direct("Why did you say it?", "\"I was frustrated with how a game had gone and made a comment I thought was harmless.\""), .direct("Did you mean to threaten {V}?", "\"No. I would never hurt an umpire. It was a poor joke, and I didn't think about how it could sound.\""), .direct("What did the other players do?", "\"They laughed at first. Then one of them said it didn't sound right, and I realized how it might look.\""), .direct("How did you feel after?", "\"I felt bad right away, and I should have apologized on the spot instead of leaving it.\""), .direct("What would you tell {V}?", "\"I'm sorry. It was a bad joke, and I'll stay away from you and keep my comments to myself.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and that's why I should have known not to say anything like that to {V.him}.\""), .cross("You said {V} wouldn't walk off the field?", "\"I said those words, and I see how they could be taken as a threat. I never meant them that way.\""), .cross("Three players heard it?", "\"Yes, and I'm sorry they had to hear it. It wasn't a good example.\""), .cross("You called it a joke?", "\"It was meant as one, but I understand that {V} didn't take it that way, and that matters.\""), .cross("You'll stay away from the games {V} umpires?", "\"I'll play on days someone else is working, or I'll skip those games altogether.\"")],
        openings: ("Before the next game {D} told {V}, an umpire, 'You won't walk off this field,' loud enough for three players to hear, and {V} filed a report with the league, and {DL} had been before this court in {PRIORDATE} over {PRIOR}.", "The defense will say it was a joke of the kind players shout at umpires every week, said in front of a crowd with a grin. {D} never raised a hand, and no one on that field acted as though they were in danger."),
        closings: ("After {PRIOR}, {D} promised an umpire, in front of three players, that {V.he} would not leave the field in one piece. The league report records it, and the players heard exactly what was said.", "A joke yelled across a ball field is not a threat unless the speaker means it to frighten. {D} never touched {V}, never followed {V.him}, and the State must prove {D} intended fear, not just heated words."),
        timeline: [(0, "Before the game: the threat.")],
        identified: "Players and the league report.",
        impact: "I don't umpire {D.his} games now. {D.He} told me before the next game that I wouldn't walk off that field, and players heard it. I've called games for years and never felt unsafe. I took a different assignment so I wouldn't have to see {D.him}.",
        genders: ["V": .male, "D": .male])

    static let ticketScalperTwo = SmallCases.make(
        key: "story.followup.ticketScalperTwo",
        category: .whiteCollar,
        headlines: ["Fake Tickets Sold Again for Different Show", "Second Ticket Scam Charge"],
        law: "falsePretenses",
        spec: "Obtained $180 from {V} by falsely representing that {D} was selling genuine tickets, on {DATE}.",
        ages: 18...40,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} sold two tickets to a basketball game that turned out to be duplicates. {V} was turned away.",
        state: [E(.digital, 3, "The Listing", "{D}'s listing."), E(.document, 2, "Payment", "$180 sent.")],
        defense: [E(.statement, 1, "Reseller", "{DL} says {D.he} bought them.")],
        role: "Venue box office manager",
        exam: [.direct("What brought two buyers to your box office?", "\"{V} arrived for a basketball game with two tickets bought online, and the scanner rejected them as duplicates of tickets already used.\""), .direct("What did your system show?", "\"Both seat numbers had been scanned at the gate earlier by another holder, so ours showed the originals were already in use.\""), .direct("How do duplicate tickets happen?", "\"A seller can screenshot or copy the same digital ticket and sell it to several people, and only the first to arrive gets in.\""), .direct("What did {V} do?", "\"{V} was turned away at the gate, came to the box office upset, and showed me the listing and payment screens.\""), .direct("What did the listing show?", "\"{DL}'s listing offered two seats at a price that looked fair, with photos copied from a ticket confirmation.\""), .direct("What did {V} pay?", "\"One hundred eighty dollars through a payment app, which {V} showed me on the phone before leaving.\""), .cross("Resale tickets are common, aren't they?", "\"Yes, many fans buy and sell tickets online, and most of those sales go through without any problem.\""), .cross("{DL} may have bought them in good faith?", "\"That's possible. I can't say where {D.he} got them or whether {D.he} knew they were duplicates.\""), .cross("The original ticket holder got in first?", "\"Yes. The scanner admits the first valid scan and rejects every later one with the same barcode.\""), .cross("You can't tell who copied the ticket?", "\"No. The system shows only the time and gate of each scan, not who sold or copied it.\""), .cross("{V} was offered a refund by the venue?", "\"No, venues don't refund resale tickets. {V} had to seek money back from the seller.\"")],
        theory: ("{D} sold fake tickets again.", "A reseller."),
        allocution: "\"I'll refund everyone. I bought those tickets from a reseller and believed they were good, and I sold them in good faith. I've been in this courtroom before, and I know it looks like a pattern. I'm sorry to {V} and the family who was turned away.\"",
        truths: ("{DL} screenshots to three buyers.", "The reseller was arrested."),
        defendant: [.direct("Where did you get the tickets?", "\"I bought them from someone online who said they couldn't use them. I paid and sold them for a small profit.\""), .direct("Did you know they were duplicates?", "\"No. I had no idea the same tickets were sold to others. I sent the screenshot as I received it.\""), .direct("Why did you resell them?", "\"I do this to make a little extra money, and I thought it was no different from many other people doing the same.\""), .direct("What did you do when {V} complained?", "\"I was surprised and told {V.him} I'd look into it. I didn't think I could get the money back from the seller.\""), .direct("Did you try to cheat {V}?", "\"No. I never planned to cheat anyone. I believed I was passing on real tickets.\""), .direct("What would you say to {V}?", "\"I'm sorry you were turned away. I'll pay you back the full one hundred eighty dollars.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I knew to be careful with resales. I should have checked the tickets myself.\""), .cross("You sold tickets that didn't work?", "\"Yes, and I should have confirmed them with the venue before selling.\""), .cross("You made a profit on them?", "\"A small one, yes, and I understand now that was wrong given what happened.\""), .cross("You can't name the person who sold them to you?", "\"I only know the username. I never met them, and I should have asked for more.\""), .cross("You'll repay {V}?", "\"Yes, I will, as soon as the court sets a plan, and I'll apologize directly.\"")],
        openings: ("{D} sold two tickets to a basketball game for $180, and when {V} reached the gate the scanner rejected both because the seats had already been scanned. {DL} came before this court in {PRIORDATE} over {PRIOR}, and the listing was in {D}'s name.", "The defense will say {D} bought the tickets honestly and resold them without any idea that they had been copied. {D} was a reseller trusting the seller, and was as surprised by the rejected scan as {V} was."),
        closings: ("The listing was {D}'s, the $180 payment went to {D}, and the seats had been used before {V} arrived. After {PRIOR}, {DL} knew what reselling tickets without checking them can mean for the buyer.", "A reseller cannot see whether a ticket has been copied, and {D} had nothing to gain from selling a ticket that would fail at the door. The State must prove {D} knew these two tickets were duplicates."),
        timeline: [(0, "Game night: the scan fails.")],
        identified: "The venue's scan.",
        impact: "My son was turned away at the door. We'd saved for those tickets for weeks and promised him a night at the game. A guard scanned the barcode and said someone else had already used it. He cried the whole way home. I'd paid ninety dollars.",
        genders: ["D": .male])

    static let cameraSmashAssault = SmallCases.make(
        key: "story.followup.cameraSmashAssault",
        category: .violent,
        headlines: ["Neighbors Fight Over Replaced Camera", "Simple Assault After Camera Smash Case"],
        law: "simpleAssault",
        spec: "Assaulted {V} by shoving {V.him}, on {DATE}.",
        ages: 24...66,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V} installed a new camera and {D} came to the fence and shoved {V.him} when {V.he} would not remove it.",
        state: [E(.video, 3, "New Camera", "{D} shoves {V} at the fence."), E(.document, 1, "Note", "A bruise.")],
        defense: [E(.statement, 1, "Reach", "{DL} says {V} reached over the fence first.")],
        role: "Sheriff's deputy",
        exam: [.direct("What were you called to that evening?", "\"{V} called about a neighbor who had come to the fence line and shoved {V.him} over a new security camera.\""), .direct("What does the camera show?", "\"The new camera shows {DL} walking up to the fence, arguing with {V}, and pushing {V.him} backward.\""), .direct("What did {V} tell you about the argument?", "\"{V} said {DL} demanded that {V.he} remove the camera pointed toward {D.his} yard, and {V.he} refused.\""), .direct("What injury did you see?", "\"A bruise on {V}'s forearm and a scrape where {V.he} stumbled against the fence post.\""), .direct("Why was there a dispute?", "\"{DL} said the camera was filming {D.his} yard and {D.he} wanted it taken down, which {V} said it wasn't doing.\""), .direct("What did {DL} tell you?", "\"{D.He} said {V} reached over the fence first, and {D.he} pushed {V.his} hand away in reaction.\""), .cross("{DL} says {V} reached over the fence?", "\"Yes, that's what {D.he} told me, but the video doesn't clearly show {V} reaching.\""), .cross("The camera angle shows only part of the fence?", "\"Yes, the view is partial, so part of the contact may be out of the frame.\""), .cross("{V}'s injury was a bruise?", "\"A bruise and a scrape, nothing that needed medical care.\""), .cross("The two have argued before?", "\"Yes, there's a history between them over the property line and the camera.\""), .cross("{DL} didn't strike {V}?", "\"On the video it looks like a shove, not a strike, and {D.he} didn't hit {V.him} afterward.\"")],
        theory: ("{D} shoved {V}.", "A reach over a fence."),
        allocution: "\"{V} installed a new camera right where I'd complained, and I went to the fence, and when {V.he} wouldn't talk I reached over to stop {V.him}. I've been in this courtroom before, and I know I should have called the sheriff. I won't go near that fence again.\"",
        truths: ("{DL} said 'take it down or else.'", "{V} had grabbed {DL}'s collar."),
        defendant: [.direct("What happened at the fence?", "\"I went over to ask {V} to take the camera down. We argued, and I pushed {V.his} arm away when it came over the fence.\""), .direct("Why were you upset about the camera?", "\"It points toward my yard and my back door. I thought {V} was watching my family.\""), .direct("Did you shove {V}?", "\"I pushed {V.his} hand away. I didn't mean to knock {V.him} down. I reacted when I felt a hand on me.\""), .direct("Did {V} reach over first?", "\"Yes. {V.He} reached across the fence and I thought {V.he} was going to grab me. I shoved to stop it.\""), .direct("What happened afterward?", "\"I went inside, and then the deputies came. I told them the same thing I'm telling you.\""), .direct("What would you tell {V}?", "\"I'm sorry things went that far. I'll talk to you through a lawyer, and I'll keep away from the fence.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I should have known to stay calm instead of putting my hands on someone.\""), .cross("You shoved {V} at the fence?", "\"I pushed {V.his} arm and {V.he} stumbled. I know that's what the video shows.\""), .cross("You could have called the sheriff about the camera?", "\"I could have, and that's the choice I keep thinking about. I let my temper get the best of me.\""), .cross("{V} was bruised and scraped?", "\"I'm sorry for that. I never meant for {V.him} to get hurt.\""), .cross("You'll stay off {V}'s side of the fence?", "\"Yes. I won't go to the fence or speak to {V.him} unless a lawyer is present.\"")],
        openings: ("After {V} installed a new camera on the fence line, {D} came over, argued, and shoved {V.him} backward when {V.he} would not take it down. The new camera recorded the shove, and {DL} had stood in this court in {PRIORDATE} over {PRIOR}.", "The defense will say {V} reached over the fence first, and {D} pushed back once in the heat of an argument between neighbors. One shove over a fence is a quarrel, not a crime."),
        closings: ("The camera shows {D} walk up to the fence, argue with {V}, and push {V.him} back hard enough to leave a bruise. After {PRIOR}, {DL} knew better than to put hands on a neighbor.", "A shove after a reach over the fence is a reaction in the moment, not a planned assault. {D} did not follow {V} or strike {V.him} again, and the State must prove more than one push between neighbors."),
        timeline: [(0, "Afternoon: the new camera.")],
        identified: "{V}'s new camera.",
        impact: "I put the camera higher, and I put it on a pole. {D.He} came to the fence and shoved me when I wouldn't take it down. I'd put it in after my packages kept being stolen. I wanted my own porch to be safe, and now my neighbor is the problem.",
        genders: ["D": .male])

    static let rideshareRunnerTwo = SmallCases.make(
        key: "story.followup.rideshareRunnerTwo",
        category: .property,
        headlines: ["Second Driver Says Passenger Ran From Fare", "Larceny Charge After Another Rideshare Run"],
        law: "misdLarceny",
        spec: "Stole $52 in transportation services from {V}, a rideshare driver, on {DATE}.",
        ages: 18...45,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, another driver said {D} ran from a $52 fare. The ride record and dash camera confirmed it.",
        state: [E(.video, 3, "Dash Camera", "{D} runs from the car."), E(.document, 2, "Fare Record", "$52 unpaid.")],
        defense: [E(.statement, 1, "Card", "{DL} says {D.his} card was declined.")],
        role: "Rideshare driver",
        exam: [.direct("What happened on your trip that night?", "\"I picked up {DL} at a bar and drove about twelve miles, and at the destination {D.he} jumped out and ran.\""), .direct("What was the fare?", "\"Fifty-two dollars for the trip, charged to the card on the app, which was declined at the end.\""), .direct("What does your dash camera show?", "\"It shows {DL} getting out at the destination, saying he'd be right back, and then running off into the dark.\""), .direct("What did you do after that?", "\"I waited several minutes, called the app, and then called the sheriff's office to report it.\""), .direct("How did the app help identify {DL}?", "\"The account name, phone number, and ride record all matched {DL}, and the card on file matched the declined payment.\""), .direct("What did {DL} say?", "\"{D.He} said {D.his} card was declined and {D.he} panicked and ran, meaning to pay later.\""), .cross("The card was declined at the end of the trip?", "\"Yes, the app notified me right after, and then {DL} ran.\""), .cross("{DL} never threatened you?", "\"No. There were no threats and no violence. {D.He} was polite during the ride.\""), .cross("{DL} could have paid in cash?", "\"That's possible, but {D.he} never offered. {D.He} left before I could ask.\""), .cross("You've been paid since?", "\"Not by {DL}. The app reimbursed a small part, and I absorbed the rest.\""), .cross("You don't know why {DL} ran?", "\"No. I only know what the camera shows and what {D.he} told the deputy later.\"")],
        theory: ("{D} ran again.", "A declined card."),
        allocution: "\"I'll pay. My card was declined at the end of that ride, and I didn't know what to do. I've been in this courtroom before and I know it looks bad. I'm sorry to the driver, and I'll pay the fifty-two dollars and a tip.\"",
        truths: ("{DL} ran from three rides.", "{DL}'s phone died."),
        defendant: [.direct("Why did you take the ride?", "\"I was far from home and had no other way back. I thought I could cover the fare when I got there.\""), .direct("What happened with the card?", "\"It was declined at the end of the ride, and I didn't have enough cash. I panicked.\""), .direct("Why did you run?", "\"I was afraid of what the driver would do and embarrassed that I couldn't pay. I ran without thinking.\""), .direct("Did you plan to leave without paying?", "\"No. I meant to pay once I got to my apartment, but I didn't think about how the driver would see it.\""), .direct("What did you do afterward?", "\"I called the app and said I'd pay, and I told the deputy the truth when he called.\""), .direct("What would you tell the driver?", "\"I'm sorry for running. I'll pay you the fifty-two dollars and I won't leave a ride without paying.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I should have known better than to take a ride I couldn't pay for.\""), .cross("You ran from a fare?", "\"I did, and I know that was wrong and unfair to the driver.\""), .cross("You knew your card might not work?", "\"I did, but I hoped it would. I should have checked before I got in.\""), .cross("The driver lost a fare and time?", "\"Yes, and I'm sorry for that. The driver did nothing wrong.\""), .cross("You'll pay back the fifty-two dollars?", "\"Yes, in full, as soon as possible, and I'll add an apology.\"")],
        openings: ("{D} rode about twelve miles in a rideshare, jumped out at the destination, and ran, leaving a $52 fare unpaid. The dash camera and the app's ride record both confirm it, and {DL} had already appeared here in {PRIORDATE} over {PRIOR}.", "The defense will say {D}'s card was declined at the end of the ride and {D} panicked, embarrassed in front of the driver. {D} meant to pay and ran out of shame, not out of a plan to cheat anyone."),
        closings: ("The dash camera shows {D} leave the car and run, the app shows the fare unpaid, and after {PRIOR} {DL} knew what a ride costs and what leaving without paying means.", "A declined card is a mistake, not a scheme. {D} had an account on the app and left a record of who {D.he} was, and the State must prove {D} intended to avoid paying from the start."),
        timeline: [(0, "Night: the ride.")],
        identified: "The dash camera.",
        impact: "It's the second time this month. I drove across town with a passenger, and at the end {D.he} said the card was declined and walked off. I can't keep absorbing fifty-dollar fares. I drive to pay my rent, and every one counts.",
        genders: ["D": .male])

    static let parkingLotDispute = SmallCases.make(
        key: "story.followup.parkingLotDispute",
        category: .publicOrder,
        headlines: ["Driver Screams at Tow Truck Driver Over Boot", "Disorderly Conduct After Boot Case"],
        law: "disorderly",
        spec: "Engaged in disorderly conduct by making a public disturbance, on {DATE}.",
        ages: 20...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} shouted at a tow driver for ten minutes and blocked the truck's path in a private lot. Deputies came.",
        state: [E(.video, 3, "Lot Camera", "{D} blocks the truck."), E(.statement, 2, "Tow Driver", "{D} cursed.")],
        defense: [E(.statement, 1, "Angry", "{DL} says {D.he} was upset about a boot.")],
        role: "Tow truck driver",
        exam: [.direct("What happened in the lot that afternoon?", "\"I was towing a car from a private lot, and {DL} came out shouting that I couldn't take it.\""), .direct("What did {DL} do?", "\"{D.He} stood in front of my truck, cursed at me for about ten minutes, and refused to move out of the way.\""), .direct("What does the lot camera show?", "\"It shows {DL} standing in the path of the truck and gesturing while I tried to pull out.\""), .direct("Why were you towing the car?", "\"The owner of the lot had called for it because it was parked in a spot reserved for tenants.\""), .direct("What did you do?", "\"I stayed in the cab, called dispatch, and asked for deputies when it was clear {DL} wouldn't move.\""), .direct("What did {DL} say about why?", "\"{D.He} said {D.he} was upset about a boot on the car and the fee that came with it.\""), .cross("{DL} didn't touch your truck?", "\"No. {D.He} didn't strike the truck or the car and didn't try to damage anything.\""), .cross("{DL} left when the deputies came?", "\"Yes, {D.he} calmed down when the deputies arrived and moved aside.\""), .cross("You've dealt with angry owners before?", "\"Many times. It's part of the job, and most of them settle down once the fee is explained.\""), .cross("No one was hurt?", "\"No one was hurt, and no property was damaged.\""), .cross("{DL} was upset about a boot?", "\"That's what {D.he} said, and I've no reason to doubt it was the cause.\"")],
        theory: ("{D} disrupted a tow.", "An angry driver."),
        allocution: "\"They'd put a boot on my car, and I was angry, and I shouted at that tow driver for ten minutes and stood in the way. I've been in this courtroom before, and I should have just called the company. I regret how I behaved.\"",
        truths: ("{DL} had been told about the boot.", "The boot was on the wrong car."),
        defendant: [.direct("Why were you shouting at the tow driver?", "\"I came out and saw my car being hooked, and I was upset about the boot and the fees I'd have to pay.\""), .direct("Why did you stand in front of the truck?", "\"I wanted to stop the tow and talk it through. I didn't think I was breaking a rule.\""), .direct("Did you mean to cause a scene?", "\"No. I was angry and embarrassed, and I let it get loud. I didn't think about the people around.\""), .direct("What happened when the deputies came?", "\"I stopped shouting and moved aside. I told them what the problem was, and they explained my options.\""), .direct("What would you do differently?", "\"I'd stay calm, ask for the paperwork, and take it up with the lot owner instead of the driver.\""), .direct("What would you say to the driver?", "\"I'm sorry for yelling. You were doing your job, and I shouldn't have taken it out on you.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I should have known better than to make a scene in a public lot.\""), .cross("You shouted for ten minutes?", "\"It may have been that long. I can't say exactly, but it was too long.\""), .cross("You blocked the truck's path?", "\"Yes, I stood in front of it. I should have stepped aside as soon as asked.\""), .cross("You cursed at the driver?", "\"I did, and I've regretted it ever since. The driver didn't deserve that.\""), .cross("You'll handle it differently next time?", "\"Yes. I'll call the owner or the sheriff and keep my voice down.\"")],
        openings: ("{D} stood in front of a tow truck in a private lot, shouted and cursed at the driver for about ten minutes, and refused to move until deputies came. The lot camera recorded it, and this was not {DL}'s first time here, after {PRIOR} in {PRIORDATE}.", "The defense will say {D} was upset about a boot and a tow that {D.he} believed were wrong, and that {D.he} was loud but never touched the driver. Anger at a tow is not a crime."),
        closings: ("The camera shows {D} blocking the truck's path and cursing for ten minutes while the driver tried to leave with the car. After {PRIOR}, {DL} knew how to handle a dispute without this.", "A loud argument over a tow is ordinary frustration, and {D} did not strike or threaten the driver. The State must prove {D} intended to disrupt and not merely to complain."),
        timeline: [(0, "Afternoon: the tow truck arrives.")],
        identified: "The lot camera.",
        genders: ["D": .male])

    static let burglaryReceiving = SmallCases.make(
        key: "story.followup.burglaryReceiving",
        category: .property,
        headlines: ["Stolen Laptop Traced to Man From Burglary Case", "Receiving Charge After Daytime Break-In"],
        law: "possStolen",
        spec: "Possessed a laptop valued at $900 belonging to {V}, knowing it stolen, on {DATE}.",
        ages: 19...45,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a laptop stolen from {V}'s home turned up at {D}'s apartment. {DL} says {D.he} bought it from a friend.",
        state: [E(.physical, 3, "The Laptop", "{V}'s laptop, serial matching.", .search), E(.document, 2, "Report", "{V}'s report.")],
        defense: [E(.statement, 1, "Friend", "{DL} says a friend sold it.")],
        role: "Sheriff's detective",
        exam: [.direct("How did the laptop come to your attention?", "\"{V} reported a burglary at {V.his} home and gave me the serial number of a laptop that was taken.\""), .direct("How did you find it?", "\"A tip and a pawn database search led me to {DL}'s apartment, where I found the laptop with the matching serial.\""), .direct("Did you have a warrant?", "\"Yes. We searched under a warrant, and I photographed the laptop where it sat on a desk before taking it.\""), .direct("What was the laptop's value?", "\"About nine hundred dollars, a recent model that {V} used for work and had paid for in full.\""), .direct("What did {DL} tell you?", "\"{D.He} said a friend sold it to {D.him} for a good price and {D.he} didn't know it was stolen.\""), .direct("Did {DL} give a name?", "\"{D.He} gave me a first name and said {D.he} didn't know a last name or a way to reach the friend.\""), .cross("{DL} didn't hide the laptop?", "\"No. It was on a desk in plain view and {D.he} let us take it without argument.\""), .cross("{DL} wasn't at {V}'s house?", "\"Nothing links {D.him} to the burglary itself. The charge is about possession, not the break-in.\""), .cross("{DL} paid for the laptop?", "\"{D.He} said so, and I haven't found evidence that disproves it.\""), .cross("Many people buy used computers from friends?", "\"Yes, and it's common, though it can be a risk when the price is low.\""), .cross("{DL} cooperated fully?", "\"Yes, {D.he} answered my questions and gave me what information {D.he} had.\"")],
        theory: ("{D} had another stolen laptop.", "A friend's sale."),
        allocution: "\"I bought that laptop from a friend for a hundred dollars, and I didn't know it was stolen. I've been in this courtroom before, and I know what that looks like. I'll return it to {V}, and I'll stop buying anything from anyone I can't trust.\"",
        truths: ("{DL}'s prints on the broken door.", "The friend was arrested."),
        defendant: [.direct("Where did you get the laptop?", "\"A friend of a friend sold it to me for three hundred dollars. He said it was his old work computer.\""), .direct("Did you know it was stolen?", "\"No. I thought it was a good deal and I never suspected it came from a burglary.\""), .direct("Why didn't you ask more questions?", "\"I should have. I was trying to save money and took his word for it. I'm ashamed now.\""), .direct("What happened when the detective came?", "\"I let {DET.him} in, showed {DET.him} the laptop, and told {DET.him} everything I knew about where I got it.\""), .direct("What do you know about the seller?", "\"Only his first name and that he's a friend of a friend. I haven't been able to find him since.\""), .direct("What would you tell {V}?", "\"I'm sorry about your burglary. I want you to have your computer back, and I'd have returned it sooner if I'd known.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and that's why I should have been more careful about what I bought.\""), .cross("You paid three hundred for a nine-hundred-dollar laptop?", "\"Yes, and I told myself it was a bargain. It was a warning I ignored.\""), .cross("You can't give a full name for the seller?", "\"No, and I regret that. I should have asked for a receipt and a name.\""), .cross("You had the laptop at your apartment?", "\"Yes, it was on my desk, and I'd been using it for a few days.\""), .cross("You'll return it to {V}?", "\"Yes, and I'll pay whatever the court sets for the trouble.\"")],
        openings: ("A laptop taken in a burglary at {V}'s home was found in {D}'s apartment, and its serial number matches the one {V} gave deputies. {DL} came before this court in {PRIORDATE} over {PRIOR}, and a pawn database search led deputies to the door.", "The defense will say {D} bought the laptop from a friend for a fair price and never suspected it was stolen. {D} kept it openly in the apartment and never hid it from anyone."),
        closings: ("The serial number matches {V}'s, the laptop was in {D}'s apartment, and after {PRIOR} {DL} knew what a cheap laptop from a friend can mean. The State will show {D} had reason to believe it was stolen.", "A friend's sale looks like any other sale, and {D} kept the laptop in plain view in {D.his} own home. The State must prove {D} knew the laptop was stolen, not just that {D} had it."),
        timeline: [(0, "Evening: the laptop is traced.")],
        identified: "A serial number.",
        impact: "My work was on it. Months of projects and client files were on that laptop, and I'd never backed them up. When the police found it in somebody's apartment, I still couldn't recover my documents. I'd almost given up. That machine was my livelihood.",
        genders: ["D": .male])

    static let pwisdAgain = SmallCases.make(
        key: "story.followup.pwisdAgain",
        category: .drugs,
        headlines: ["Drugs Found in Car at Traffic Stop Weeks After Earlier Case", "Second Schedule II Charge"],
        law: "possSchedII",
        spec: "Knowingly possessed cocaine, a Schedule II controlled substance, on {DATE}.",
        ages: 21...50,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a deputy found a small bag of cocaine in {D}'s console. {DL} says it belonged to a passenger.",
        state: [E(.physical, 3, "The Bag", "A bag of cocaine.", .search), E(.forensic, 2, "Lab", "Cocaine.")],
        defense: [E(.statement, 1, "Passenger", "{DL} says a passenger left it.")],
        role: "Sheriff's narcotics detective",
        exam: [.direct("What led you to {DL}'s vehicle?", "\"I stopped it for a traffic violation and noticed an odor and a small bag in the center console during the stop.\""), .direct("What did you find?", "\"A small bag of white powder in the console, within easy reach of the driver and passenger seats.\""), .direct("What did the lab report say?", "\"The State Crime Lab identified the powder as cocaine, a Schedule II controlled substance.\""), .direct("Who was in the vehicle?", "\"{DL} was driving, and a passenger sat in the front seat. The bag was between them.\""), .direct("What did {DL} say about the bag?", "\"{D.He} said it belonged to the passenger, who left it there earlier in the evening.\""), .direct("What did you do with the evidence?", "\"I photographed it where it was, bagged and sealed it, logged it, and sent it to the lab with a request.\""), .cross("The bag was in the center console, shared by both seats?", "\"Yes, the console is between the driver and passenger and either could reach it.\""), .cross("The passenger was never charged?", "\"The passenger denied it and left before we finished. We chose to proceed on {DL} as driver and owner.\""), .cross("There was only a small amount?", "\"Yes, a small bag consistent with personal use, not an amount for sale.\""), .cross("You found no scales or cash?", "\"Right. There was nothing else in the car that suggested sales.\""), .cross("{DL} was cooperative?", "\"Yes, {D.he} was polite and answered my questions during the stop.\"")],
        theory: ("{D} had cocaine again.", "A passenger's bag."),
        allocution: "\"That bag in my console belonged to a passenger I gave a ride, and I didn't know it was there. I've been in this courtroom before, and I know I should be more careful about who rides with me. I'll pay whatever the court sets.\"",
        truths: ("{DL}'s prints on the bag.", "The passenger confirmed."),
        defendant: [.direct("Whose bag was it?", "\"It belonged to a passenger who'd ridden with me that night. I didn't see him put it in the console.\""), .direct("Did you know it was there?", "\"No. I'd lent the passenger the front seat, and I didn't look in the console before driving.\""), .direct("Have you used cocaine?", "\"In the past, yes. I've worked to stay away from it, and I haven't used since the earlier case.\""), .direct("What happened at the stop?", "\"The deputy asked about the console. I told him it wasn't mine, and I told him who sat there.\""), .direct("Who was the passenger?", "\"A man I'd known from work. I know his first name, and I haven't talked to him since that night.\""), .direct("What would you tell the court?", "\"The bag wasn't mine. I'd ask the court to consider that I've been trying to stay clean.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, over drugs, and I know why that makes this look bad. I'm telling the truth.\""), .cross("The bag was in your console?", "\"It was, but I didn't know it was there. I'd just given someone a ride.\""), .cross("You can't give a last name for the passenger?", "\"No. I knew him casually and never needed it. I regret that now.\""), .cross("It was cocaine?", "\"Yes, that's what the lab says. I don't dispute that part, only that it was mine.\""), .cross("You'll be more careful who you let in your car?", "\"Yes. I won't offer rides to people I don't know well, and I'll check the console.\"")],
        openings: ("A deputy stopped {D} for a traffic violation, noticed an odor and a small bag in the center console, and the lab confirmed the white powder was cocaine, and {DL} had faced this court in {PRIORDATE} over {PRIOR}.", "The defense will say the bag belonged to a passenger who left it behind in the console, and that {D} did not know it was there. A bag in a shared console is not proof of whose it is."),
        closings: ("The cocaine sat in the console beside {D}, within easy reach of the driver's seat, and after {PRIOR} {DL} knew exactly what that bag was and what it meant to keep it in the car.", "Presence in a car is not possession, and a shared console holds what passengers leave. The State must prove {D} knew the bag was there and meant to keep it."),
