        spec: "Violated a domestic violence protective order by contacting {V}, on {DATE}.",
        ages: 22...50,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} sent {V} nine text messages after a protective order was entered. {V} kept every one.",
