        defense: [E(.statement, 1, "Wrong Number", "{DL} says the texts were to a friend.")],
        role: "Sheriff's deputy",
        exam: [.direct("What were you asked to investigate?", "\"{V} reported that {DL} had sent nine text messages after a domestic violence protective order was entered.\""), .direct("What does the order say?", "\"It prohibits {DL} from contacting {V} in any way, including by text, phone, social media, or through others.\""), .direct("What did the messages say?", "\"They asked {V} to talk, said {D.he} missed {V.him}, and one said {D.he} needed to explain what happened.\""), .direct("How did {V} preserve them?", "\"{V} kept every message on the phone, took screenshots, and brought them to me with the dates and times.\""), .direct("How did you confirm they came from {DL}?", "\"The phone number matched {DL}'s, and the carrier records tied the account to {D.him}.\""), .direct("What did {DL} say?", "\"{D.He} said the texts were meant for a friend with a similar name and went to {V} by mistake.\""), .cross("The messages could have been sent in error?", "\"In theory, but they used {V}'s name and referred to events only the two of them would know.\""), .cross("{DL} didn't threaten {V}?", "\"No threats appear in the messages. They were pleas and explanations, though still forbidden by the order.\""), .cross("{V} didn't reply?", "\"No, {V} didn't answer any of them and reported them to us.\""), .cross("The messages were sent over several days?", "\"Over about a week, nine messages in all.\""), .cross("{DL} stopped when you called?", "\"Yes, the texts stopped after I spoke to {D.him} about the order.\"")],
        theory: ("{D} contacted {V} under an order.", "Texts to a friend."),
        allocution: "\"I thought I was texting a friend, and I mixed up the number. I've been in this courtroom before, and I know there's an order. I never meant to contact {V}. I'll delete the number and stay away.\"",
        truths: ("{DL} had {V}'s number saved.", "The number was reassigned."),
        defendant: [.direct("Why did you text {V}?", "\"I wanted to explain myself and I missed {V.him}. I let my feelings get ahead of the order.\""), .direct("Did you know the order was in effect?", "\"Yes, I knew about it. I wasn't thinking about it when I picked up the phone.\""), .direct("Did you mean to send them to {V}?", "\"I meant them for {V}, but I also sent a couple to a friend whose name is close. I was confused and upset.\""), .direct("What did you intend?", "\"I never meant to scare or threaten {V.him}. I only wanted to talk, and I should have left it alone.\""), .direct("What happened when the deputy called?", "\"I stopped immediately, and I told the deputy I understood and wouldn't contact {V.him} again.\""), .direct("What would you tell {V}?", "\"I'm sorry. I broke the order and I won't contact you again. I'll leave you alone completely.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and that's why the order exists. I should have respected it.\""), .cross("You sent nine messages after the order?", "\"I did, and I know how that looks. I take responsibility for it.\""), .cross("You told the deputy they were to a friend?", "\"I did, and that wasn't the whole truth. I'm sorry I wasn't honest.\""), .cross("The order bars all contact?", "\"Yes, and I understand that. Texting counts, and I shouldn't have.\""), .cross("You'll stay away from {V}?", "\"Yes. I'll delete {V.his} number and not contact {V.him} in any way again.\"")],
        openings: ("After a domestic violence protective order was entered, {D} sent {V} nine text messages, and {V} saved every one and brought them to deputies. {DL} came before this court in {PRIORDATE} over {PRIOR}, and the order bars contact by text.", "The defense will say the texts were meant for a friend and went to {V}'s number by mistake. {D} never meant to contact {V}, and the messages show no threat or demand."),
        closings: ("The order bars all contact, including text, and nine messages came from {D}'s phone after it was entered. After {PRIOR}, {DL} knew exactly what the order meant and chose to send them anyway.", "A message sent to the wrong number is a mistake, not a violation. The State must prove {D} meant the texts for {V}, and nine messages that ask for nothing do not show that."),
