        state: [E(.document, 3, "The Check", "A forged signature."), E(.forensic, 2, "Exam", "Probably forged.")],
        defense: [E(.statement, 1, "Authorized", "{DL} says {V} approved it.")],
        role: "Forensic document examiner",
        exam: [.direct("What is your work?", "\"I'm a forensic document examiner. I compare handwriting and signatures on checks and documents for law enforcement.\""), .direct("What were you asked to examine?", "\"A check for eighteen hundred dollars, payable to {V}, deposited by {DL}, and signature samples from the account holder.\""), .direct("What method did you use?", "\"I compared the questioned signature to known samples, looking at slant, pressure, letter forms, and the rhythm of the stroke.\""), .direct("What did you conclude?", "\"The signature on the check was probably not written by the account holder. It showed hesitation and differences in letter formation.\""), .direct("What does 'probably' mean in your field?", "\"It means the evidence points to a forged signature, but the sample available wasn't enough for a definite conclusion.\""), .direct("What did {DL} say about the check?", "\"{D.He} said {V} approved the check and that {D.he} was only depositing it for {V.him}.\""), .cross("You can't say who wrote the signature?", "\"No. I can only say whether it matches the account holder, not who actually signed it.\""), .cross("Your conclusion is 'probably', not 'definitely'?", "\"Yes, because I had limited known samples. A larger sample might have supported a stronger conclusion.\""), .cross("{DL} could have received the check already signed?", "\"That's possible. I can't say whether {D.he} knew it was forged.\""), .cross("People's signatures vary from day to day?", "\"They do, and I accounted for that, but this one varied beyond a normal range.\""), .cross("You didn't see anyone sign it?", "\"No. My work is limited to comparing the writing on the page.\"")],
        theory: ("{D} forged again.", "An approved check."),
        allocution: "\"I stamped that check because I was told to by my new employer, and I deposited it believing it was approved. I've been in this courtroom before, and I know that doesn't help me. I regret the trouble, and I'll cooperate fully.\"",
        truths: ("{DL}'s practice sheets.", "A stamp."),
        defendant: [.direct("Where did you get the check?", "\"From the owner of the company I started working for. He handed it to me as a payment for a job.\""), .direct("What did you do with it?", "\"I deposited it at my bank, the way I would with any paycheck. I didn't suspect anything wrong.\""), .direct("Did you sign the check?", "\"No. I never signed it or touched the signature line. It was written when I received it.\""), .direct("What did {V} say about the check?", "\"{V} told me it was approved and that I could deposit it. I didn't know it wasn't.\""), .direct("What happened when the bank questioned it?", "\"They told me the signature didn't match, and I told them where it came from.\""), .direct("What would you tell the court?", "\"I wasn't trying to forge anything. I believed the check was real, and I'd ask the court to see that.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and that's why I should have been more careful about what I deposited.\""), .cross("You deposited a check with a forged signature?", "\"I did, but I didn't know it was forged. I thought it was legitimate pay.\""), .cross("The signature didn't match?", "\"So the examiner says. I couldn't tell by looking, and I'm sorry about the trouble.\""), .cross("You can't prove {V} approved it?", "\"I have only my word and {V}'s conversation. I should have asked for it in writing.\""), .cross("You'll cooperate with the bank?", "\"Yes. I'll help them trace where the check came from and repay if I'm found responsible.\"")],
        openings: ("{D} deposited an $1,800 check from a new employer's account, and {V} noticed the signature was not the one on file. A forensic examiner compared the signature to samples and says it is probably forged, and {DL} had been before this court in {PRIORDATE} over {PRIOR}.", "The defense will say {V} approved the check and {D} had every reason to trust it. {D} did not sign it and did not know anything was wrong with the signature."),
